def utc_now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def getenv_bool(name: str, default: bool) -> bool:
    raw = (os.getenv(name) or "").strip().lower()
    if not raw:
        return default
    return raw in {"1", "true", "yes", "on"}


def getenv_int(name: str, default: int) -> int:
    raw = (os.getenv(name) or "").strip()
    try:
        return int(raw) if raw else default
    except Exception:
        return default


def getenv_float(name: str, default: float) -> float:
    raw = (os.getenv(name) or "").strip()
    try:
        return float(raw) if raw else default
    except Exception:
        return default


def runtime_elapsed_seconds() -> float:
    return time.monotonic() - RUN_STARTED_MONOTONIC


def runtime_remaining_seconds() -> float:
    max_seconds = getenv_int("REGION_TALK_NOTEBOOK_MAX_RUNTIME_SECONDS", 18 * 60)
    return float(max_seconds) - runtime_elapsed_seconds()


def runtime_budget_ok(*, reserve_seconds: int = 120) -> bool:
    return runtime_remaining_seconds() > reserve_seconds


def should_defer_acquisition_for_critical_work(posts_count: int) -> bool:
    """Protect critical handoff without wasting the rest of a healthy run.

    The previous boolean stopped every acquisition stage after a single exact
    post, even with more than 17 minutes left.  E5 model startup dominates a
    small batch, so scoring one post instead of a bounded high-probability batch
    is product-negative.  Defer only when the critical batch is already useful
    on its own or when the durable scoring/write tail is genuinely at risk.
    """
    if not getenv_bool("REGION_TALK_DEFER_DISCOVERY_ON_CRITICAL_WORK", True):
        return False
    min_posts = max(1, getenv_int("REGION_TALK_CRITICAL_WORK_DEFER_MIN_POSTS", 8))
    min_remaining = max(0, getenv_int("REGION_TALK_CRITICAL_WORK_CONTINUE_MIN_REMAINING_SECONDS", 600))
    return int(posts_count or 0) >= min_posts or runtime_remaining_seconds() <= min_remaining


def runtime_aware_posts_to_score_limit(
    configured_max: int,
    posts_available: int,
    *,
    remaining_seconds: float | None = None,
) -> tuple[int, dict[str, Any]]:
    """Reserve the expensive queue/YDB tail before starting E5 scoring.

    Source-count budgets are not a reliable proxy for work: exact-post,
    keyword and history lanes can make five sources yield forty posts.  Use the
    measured remaining wall time and preserve a fixed tail for queue assembly
    and durable YDB writes; the KO-priority sort then decides which posts use
    the bounded scoring slots.
    """
    available_posts = max(0, int(posts_available or 0))
    configured = max(0, int(configured_max or 0))
    if configured <= 0:
        configured = available_posts
    remaining = runtime_remaining_seconds() if remaining_seconds is None else float(remaining_seconds)
    fixed_tail = max(0.0, getenv_float("REGION_TALK_RUNTIME_FIXED_TAIL_SECONDS", 300.0))
    seconds_per_post = max(0.5, getenv_float("REGION_TALK_RUNTIME_SECONDS_PER_SCORED_POST", 5.0))
    minimum = max(1, getenv_int("REGION_TALK_RUNTIME_MIN_POSTS_TO_SCORE", 8))
    dynamic = max(minimum, int(max(0.0, remaining - fixed_tail) // seconds_per_post))
    limit = min(available_posts, configured, dynamic)
    return limit, {
        "configured_max": configured,
        "posts_available": available_posts,
        "remaining_seconds": round(remaining, 1),
        "fixed_tail_seconds": round(fixed_tail, 1),
        "seconds_per_scored_post": round(seconds_per_post, 2),
        "dynamic_max": dynamic,
        "selected_limit": limit,
    }


def start_region_talk_stack_watchdog() -> None:
    """Emit Python stack dumps during opaque Kaggle stalls."""
    global _REGION_TALK_STACK_WATCHDOG_STARTED
    if _REGION_TALK_STACK_WATCHDOG_STARTED:
        return
    if not getenv_bool("REGION_TALK_ENABLE_STACK_WATCHDOG", True):
        return
    interval = getenv_int("REGION_TALK_STACK_WATCHDOG_SECONDS", 120)
    if interval <= 0:
        return
    try:
        faulthandler.enable(file=sys.stderr, all_threads=True)
        # One all-thread dump is enough to diagnose an opaque startup/stall.
        # Repeating the dump while CPython is executing a C regex after the E5
        # native runtime has been loaded/unloaded coincided with a hard Kaggle
        # interpreter crash at the second watchdog boundary.  Keep the useful
        # first dump, but make repeated native signal activity opt-in.  The
        # source-queue stage has its own structured progress events below.
        repeat = getenv_bool("REGION_TALK_STACK_WATCHDOG_REPEAT", False)
        faulthandler.dump_traceback_later(interval, repeat=repeat, file=sys.stderr)
        atexit.register(lambda: faulthandler.cancel_dump_traceback_later())
        _REGION_TALK_STACK_WATCHDOG_STARTED = True
        print(
            f"[region-talk] stack_watchdog_enabled interval_seconds={interval} repeat={str(repeat).lower()}",
            flush=True,
        )
    except Exception as exc:
        print(f"[region-talk] stack_watchdog_enable_failed {type(exc).__name__}: {str(exc)[:160]}", flush=True)


def stable_hash(*parts: Any, length: int = 16) -> str:
    h = hashlib.sha256()
    for part in parts:
        h.update(str(part or "").strip().lower().encode("utf-8"))
        h.update(b"\0")
    return h.hexdigest()[:length]


def canonical_handle(value: str) -> str:
    raw = (value or "").strip()
    raw = re.sub(r"^https?://t\.me/", "@", raw, flags=re.I)
    raw = re.sub(r"^https?://(?:www\.)?vk\.(?:com|ru)/", "@", raw, flags=re.I)
    if raw and not raw.startswith("@") and re.fullmatch(r"[A-Za-z0-9_\.]+", raw):
        raw = "@" + raw
    return raw


def seed_sort_number(value: Any) -> int:
    m = re.search(r"\d+", str(value or ""))
    return int(m.group(0)) if m else 999999


def canonical_source_url(platform: str, handle: str, url: str) -> str:
    if url:
        raw = url.strip()
        if platform == "telegram":
            m = re.search(r"(?:t\.me|telegram\.me)/(@?[A-Za-z0-9_]{4,})(?:/)?(?:\?.*)?$", raw, re.I)
            if m:
                return "https://t.me/" + m.group(1).lstrip("@")
        if platform in {"vk", "vkvideo"}:
            m = re.search(r"vk\.(?:com|ru)/([A-Za-z0-9_.-]+)", raw, re.I)
            if m:
                ident = m.group(1)
                # `club<ID>`, `public<ID>` and `id<ID>` are complete VK
                # identities.  Prefix stripping used to turn a community into
                # a positive user id and even corrupted ordinary aliases such
                # as `publicist` -> `ist` and `clubhouse` -> `house`.
                if re.fullmatch(r"(?:club|public|id)\d+", ident, flags=re.I):
                    return "https://vk.com/" + ident
                if ident.isdigit():
                    return "https://vk.com/club" + ident
                return "https://vk.com/" + ident
        return raw.rstrip("/")
    h = canonical_handle(handle).lstrip("@")
    if not h:
        return ""
    if platform == "telegram":
        return f"https://t.me/{h}"
    if platform in {"vk", "vkvideo"}:
        return f"https://vk.com/{h}"
    return h




VK_NON_SOURCE_PATHS = {
    "video", "videos", "clip", "clips", "feed", "search", "places", "market",
    "audio", "audios", "albums", "album", "photos", "photo", "app", "apps",
    "im", "groups", "groups_create", "mail", "away", "share", "login", "join",
}


def _url_host_path(url: str) -> tuple[str, str]:
    raw = (url or "").strip()
    if raw.startswith("@"):
        return "", raw
    try:
        parsed = urllib.parse.urlparse(raw if re.match(r"^[a-z][a-z0-9+.-]*://", raw, re.I) else "https://" + raw.lstrip("/"))
        return (parsed.netloc or "").lower(), (parsed.path or "").strip("/")
    except Exception:
        return "", ""


def target_source_url_reason(platform: str, url: str) -> str:
    """Guardrail for the durable source queue: only real TG channels and VK walls/communities.

    This is URL-shape validation, not content semantics. It prevents search/result/media
    pages (tgstat search, vk video, web pages) from becoming durable scan sources.
    """
    p = (platform or "").strip().lower()
    raw = (url or "").strip()
    host, path = _url_host_path(raw)
    first = (path.split("/", 1)[0] if path else "").lower()
    if p == "telegram":
        if host not in {"t.me", "telegram.me"}:
            return "telegram_source_must_be_t_me_channel"
        if "/" in path:
            return "telegram_source_not_public_channel_url"
        if not first or first in {"s", "c", "joinchat", "+", "share", "addstickers", "proxy", "iv"}:
            return "telegram_source_not_public_channel_url"
        if not re.fullmatch(r"[a-z0-9_]{4,}", first, re.I):
            return "telegram_source_handle_invalid"
        return "ok"
    if p == "vk":
        if host not in {"vk.com", "www.vk.com", "m.vk.com"}:
            return "vk_source_must_be_vk_com_wall_or_community"
        if not first or first in VK_NON_SOURCE_PATHS or re.match(r"(?:video|clip|photo|album|doc|story|market)-?", first, re.I):
            return "vk_source_not_wall_or_community_url"
        if first.startswith("wall") and "_" in first:
            return "vk_source_not_wall_or_community_url"
        if re.fullmatch(r"(?:club|public)\d+", first, re.I) or re.fullmatch(r"wall-?\d+", first, re.I) or re.fullmatch(r"[a-z0-9_.-]{3,}", first, re.I):
            return "ok"
        return "vk_source_identifier_invalid"
    return "unsupported_platform_for_source_queue"


def is_target_source_url(platform: str, url: str) -> bool:
    return target_source_url_reason(platform, url) == "ok"

def canonical_source_key(platform: str, handle: str = "", url: str = "") -> str:
    p = (platform or "").strip().lower()
    cu = canonical_source_url(p, handle, url).lower().rstrip("/")
    if p == "telegram":
        h = canonical_handle(handle or cu).lstrip("@").lower()
        if h:
            return "telegram:" + h
    if p.startswith("vk"):
        return "vk:" + re.sub(r"^https://vk\.com/", "", cu)
    return (p or "unknown") + ":" + (cu or canonical_handle(handle).lower())




def normalize_source_platform(value: str, url: str = "") -> str:
    raw = (value or "").strip().lower().replace("_", "-")
    low_url = (url or "").strip().lower()
    if raw in {"telegram", "tg", "telegram-channel", "telegram channel", "telegram_post", "telegram-post"} or "t.me/" in low_url or "telegram.me/" in low_url:
        return "telegram"
    if raw in {"vk", "vkontakte", "vk-public", "vk public", "vk-community", "vk community", "vk group", "vk_group"} or "vk.com/" in low_url or "vk.ru/" in low_url:
        if "video" in raw:
            return "vkvideo"
        return "vk"
    if raw in {"youtube", "youtube-channel", "youtube channel"} or "youtube.com" in low_url or "youtu.be" in low_url:
        return "youtube"
    if raw in {"dzen", "zen", "dzen-channel", "dzen channel"} or "dzen.ru" in low_url:
        return "dzen"
    return raw or "unknown"

def load_dotenv(path: Path) -> None:
    if not path.exists():
        return
    for line in path.read_text(encoding="utf-8", errors="ignore").splitlines():
        if not line.strip() or line.lstrip().startswith("#") or "=" not in line:
            continue
        k, v = line.split("=", 1)
        k = k.strip()
        v = v.strip().strip('"').strip("'")
        if k and k not in os.environ:
            os.environ[k] = v


def load_kaggle_user_secrets() -> dict[str, Any]:
    names = [
        "REGION_TALK_YDB_SERVICE_ACCOUNT_KEY_JSON",
        "REGION_TALK_YDB_IAM_TOKEN",
        "YDB_ACCESS_TOKEN",
    ]
    extra = (os.getenv("REGION_TALK_KAGGLE_SECRET_NAMES") or "").strip()
    if extra:
        names.extend([x.strip() for x in re.split(r"[,;\\s]+", extra) if x.strip()])
    names = list(dict.fromkeys(names))
    try:
        from kaggle_secrets import UserSecretsClient  # type: ignore
    except Exception as exc:
        return {"ok": False, "source": "kaggle_user_secrets", "error": type(exc).__name__, "loaded": []}
    loaded: list[str] = []
    errors: list[str] = []
    client = UserSecretsClient()
    for name in names:
        if os.getenv(name):
            continue
        try:
            value = client.get_secret(name)
            if value is not None and str(value).strip():
                os.environ.setdefault(name, str(value))
                loaded.append(name)
        except Exception as exc:
            errors.append(f"{name}:{type(exc).__name__}")
    return {"ok": bool(loaded), "source": "kaggle_user_secrets", "loaded": loaded, "errors": errors[:5]}


def load_split_runtime_from_kaggle_input() -> dict[str, Any]:
    roots = [Path("/kaggle/input"), Path.cwd()]
    config: dict[str, Any] = {}
    secret_files: list[Path] = []
    key_files: list[Path] = []
    for root in roots:
        if not root.exists():
            continue
        for p in root.rglob("region_talk_run_config.json"):
            try:
                config.update(json.loads(p.read_text(encoding="utf-8")))
            except Exception:
                pass
        secret_files.extend(root.rglob("region_talk_secrets.enc"))
        key_files.extend(root.rglob("region_talk_fernet.key"))
    if secret_files and key_files:
        try:
            from cryptography.fernet import Fernet

            def _slug(path: Path, prefix: str) -> str:
                name = path.parent.name
                return name[len(prefix):] if name.startswith(prefix) else name

            key_by_slug = {_slug(k, "region-talk-key-"): k for k in key_files}
            pairs: list[tuple[Path, Path]] = []
            for secret_file in secret_files:
                slug = _slug(secret_file, "region-talk-secrets-")
                key_file = key_by_slug.get(slug)
                if key_file:
                    pairs.append((secret_file, key_file))
            # Backward compatible case: older runner may mount both files in one dataset folder.
            key_by_parent = {k.parent.resolve(): k for k in key_files}
            for secret_file in secret_files:
                key_file = key_by_parent.get(secret_file.parent.resolve())
                if key_file and (secret_file, key_file) not in pairs:
                    pairs.append((secret_file, key_file))
            for secret_file in secret_files:
                for key_file in key_files:
                    if (secret_file, key_file) not in pairs:
                        pairs.append((secret_file, key_file))
            failures: list[str] = []
            loaded = False
            for secret_file, key_file in pairs:
                try:
                    secrets = json.loads(Fernet(key_file.read_bytes().strip()).decrypt(secret_file.read_bytes()).decode("utf-8"))
                    for k, v in secrets.items():
                        if v is not None and str(v).strip():
                            os.environ.setdefault(str(k), str(v))
                    loaded = True
                    break
                except Exception as pair_exc:
                    failures.append(f"{secret_file.parent.name}+{key_file.parent.name}:{type(pair_exc).__name__}")
                    continue
            if not loaded:
                raise RuntimeError("no matching region_talk_secrets.enc/region_talk_fernet.key pair; " + "; ".join(failures[:5]))
        except Exception as exc:
            raise RuntimeError(f"failed to load encrypted Region Talk secrets: {type(exc).__name__}") from exc
    load_kaggle_user_secrets()
    return config


def validate_required_ydb_runtime_credential() -> None:
    """Fail before YDB SDK metadata fallback when a dedicated key is required.

    Kaggle is not a Yandex Compute VM.  Letting ``credentials_from_env`` fall
    through to ``169.254.169.254`` turns one missing User Secret into several
    opaque metadata timeouts.  The launcher already makes the service-account
    contract explicit; enforce the same contract inside the worker after the
    per-run config and Kaggle User Secrets have both been loaded.
    """
    if not getenv_bool("REGION_TALK_REQUIRE_NONINTERACTIVE_YDB_CREDENTIAL", False):
        return
    if (os.getenv("REGION_TALK_YDB_SERVICE_ACCOUNT_KEY_JSON") or "").strip():
        return
    if getenv_bool("REGION_TALK_ALLOW_KAGGLE_YDB_SECRET", False):
        raise RuntimeError(
            "REGION_TALK_YDB_SERVICE_ACCOUNT_KEY_JSON Kaggle User Secret is required "
            "but was not loaded; refusing YDB metadata-credential fallback"
        )
    raise RuntimeError(
        "REGION_TALK_REQUIRE_NONINTERACTIVE_YDB_CREDENTIAL=1 requires "
        "REGION_TALK_YDB_SERVICE_ACCOUNT_KEY_JSON"
    )


class Status:
    def __init__(self) -> None:
        self.client = None
        self.seq = 0
        try:
            from kaggle_status_client import KaggleStatusClient  # type: ignore
            if getenv_bool("REGION_TALK_KAGGLE_STATUS_STDOUT", False):
                self.client = KaggleStatusClient.discover()
            else:
                self.client = KaggleStatusClient.discover(log=lambda _message: None)
        except Exception:
            self.client = None
        self.events: list[dict[str, Any]] = []
        live_path = os.getenv("REGION_TALK_LIVE_EVENT_LOG_PATH") or "/kaggle/working/region_talk_run_events_live.jsonl"
        if live_path.startswith("/kaggle/") and not Path("/kaggle").exists():
            live_path = str(Path.cwd() / "region_talk_run_events_live.jsonl")
        self.live_events_path = Path(live_path)

    def _append_live_event(self, clean: dict[str, Any]) -> None:
        """Write an immediate local event log independent of YDB/callbacks."""
        try:
            self.live_events_path.parent.mkdir(parents=True, exist_ok=True)
            safe = {k: v for k, v in clean.items() if k.lower() not in {"token", "callback_token"}}
            with self.live_events_path.open("a", encoding="utf-8") as fh:
                fh.write(json.dumps(safe, ensure_ascii=False, sort_keys=True) + "\n")
                fh.flush()
                try:
                    os.fsync(fh.fileno())
                except Exception:
                    pass
        except Exception as exc:
            print(f"[region-talk] live_event_log_failed {type(exc).__name__}: {str(exc)[:160]}", flush=True)

    def _should_print_event(self, name: str) -> bool:
        if getenv_bool("REGION_TALK_STDOUT_ALL_EVENTS", False):
            return True
        heartbeat_names = {
            "alive",
            "text_embedding_model_pass_alive",
            "vector_scoring_alive",
            "final_verifier_alive",
            "source_profile_build_alive",
            "keyword_discovery_alive",
            "similar_discovery_alive",
        }
        if name in heartbeat_names:
            return getenv_bool("REGION_TALK_STDOUT_HEARTBEATS", False)
        return True

    def event(self, name: str, **payload: Any) -> None:
        self.seq += 1
        clean = {k: v for k, v in payload.items() if v is not None}
        clean.setdefault("event_name", name)
        clean.setdefault("run_id", os.getenv("REGION_TALK_RUN_ID") or "")
        clean.setdefault("event_seq", self.seq)
        clean.setdefault("created_at", utc_now_iso())
        self.events.append(clean)
        if self._should_print_event(name):
            print(f"[region-talk] {name} {json.dumps({k:v for k,v in clean.items() if k not in {'token'}}, ensure_ascii=False)[:800]}", flush=True)
        self._append_live_event(clean)
        try:
            write_region_talk_business_heartbeat(clean)
        except Exception as exc:
            print(f"[region-talk] business_heartbeat_ydb_failed {type(exc).__name__}: {str(exc)[:160]}", flush=True)
        if self.client:
            try:
                self.client.event(name, phase=clean.get("phase"), status=clean.get("status"), progress=clean)
            except Exception:
                pass


@dataclass
class Seed:
    source_seed_id: str
    platform: str
    source_title: str
    handle: str
    url: str
    source_kind: str
    source_scope_guess: str
    priority: int
    discovered_from: str
    discovered_from_url: str
    why_seeded: str
    expected_value: str
    known_risks: str
    initial_status: str
    monitoring_enabled: bool
    rights_policy: str
    notes: str

    @property
    def source_id(self) -> str:
        return "src_" + stable_hash(self.platform, canonical_source_url(self.platform, self.handle, self.url))

    @property
    def canonical_url(self) -> str:
        return canonical_source_url(self.platform, self.handle, self.url)


def find_seed_file(config: dict[str, Any]) -> Path:
    candidates = []
    for raw in [os.getenv("REGION_TALK_SEED_FILE"), config.get("seed_file"), "seed-sources-v2.csv", "docs/features/region-talk-channel/seed-sources-v2.csv", "seed-sources-v1.csv", "docs/features/region-talk-channel/seed-sources-v1.csv"]:
        if raw:
            candidates.append(Path(str(raw)))
    for root in [Path.cwd(), Path(__file__).resolve().parent, Path("/kaggle/input")]:
        if root.exists():
            candidates.extend(root.rglob("seed-sources-v2.csv"))
            candidates.extend(root.rglob("seed-sources-v1.csv"))
    for p in candidates:
        if p.exists():
            return p
    raise FileNotFoundError("seed-sources-v2.csv/seed-sources-v1.csv not found")


def load_seeds(path: Path) -> list[Seed]:
    with path.open("r", encoding="utf-8-sig", newline="") as f:
        rows = list(csv.DictReader(f))
    seeds: list[Seed] = []
    for row in rows:
        seeds.append(Seed(
            source_seed_id=str(row.get("source_seed_id") or "").strip(),
            platform=str(row.get("platform") or "").strip().lower(),
            source_title=str(row.get("source_title") or "").strip(),
            handle=canonical_handle(str(row.get("handle") or "").strip()),
            url=str(row.get("url") or "").strip(),
            source_kind=str(row.get("source_kind") or "").strip(),
            source_scope_guess=str(row.get("source_scope_guess") or "").strip(),
            priority=getenv_int("_NO_SUCH_ENV", int(str(row.get("priority") or "999").strip() or "999")),
            discovered_from=str(row.get("discovered_from") or "").strip(),
            discovered_from_url=str(row.get("discovered_from_url") or "").strip(),
            why_seeded=str(row.get("why_seeded") or "").strip(),
            expected_value=str(row.get("expected_value") or "").strip(),
            known_risks=str(row.get("known_risks") or "").strip(),
            initial_status=str(row.get("initial_status") or "").strip(),
            monitoring_enabled=str(row.get("monitoring_enabled") or "").strip().lower() in {"1","true","yes","on"},
            rights_policy=str(row.get("rights_policy") or "unknown").strip() or "unknown",
            notes=str(row.get("notes") or "").strip(),
        ))
    return seeds



