def image_candidate_projection_fingerprint(row: dict[str, Any]) -> str:
    """Fingerprint only CandidateReport-owned image admission fields.

    The image worker can add scores between the early and final handoffs.  Its
    fields are deliberately excluded so the final handoff is skipped only
    when CandidateReport's own richer source/text/vector projection is still
    identical to the early one.
    """
    payload = {field: row.get(field) for field in IMAGE_CANDIDATE_PROJECTION_FIELDS}
    return hashlib.sha256(
        json.dumps(payload, ensure_ascii=False, sort_keys=True, default=str).encode("utf-8")
    ).hexdigest()


def image_queue_rows_for_ydb_write(
    rows: list[dict[str, Any]],
    *,
    run_now: str,
    exclude_keys: set[str] | None = None,
) -> list[dict[str, Any]]:
    """Return only CandidateReport-owned image queue transitions.

    ImageDiagnostic and CandidateReport intentionally run in parallel.  The
    former owns leases and actual-image scores, while the latter owns creation
    and publication-eligibility transitions.  Re-upserting every historical
    image row from CandidateReport's start-of-run snapshot can overwrite a
    score written seconds earlier by ImageDiagnostic.  Only new rows and rows
    whose queue status changed in this CandidateReport run are therefore safe
    to hand off.  Rows already written by the early handoff are excluded from
    the final handoff so a newly created row cannot be scored between two stale
    CandidateReport writes and then be downgraded.
    """
    if not getenv_bool("REGION_TALK_YDB_IMAGE_QUEUE_WRITE_CHANGED_ONLY", True):
        excluded = exclude_keys or set()
        return [row for row in rows if image_queue_row_key(row) not in excluded]
    excluded = exclude_keys or set()
    selected: list[dict[str, Any]] = []
    for row in rows:
        key = image_queue_row_key(row)
        if not key or key in excluded:
            continue
        is_new = str(row.get("added_at") or "") == str(run_now or "")
        # ``status_changed_this_run`` is a persisted ledger field.  Historical
        # rows can therefore still contain ``true`` on the next CandidateReport
        # run.  Treat it as a current transition only when its transition
        # timestamp is this build's ``run_now``; otherwise a stale marker can
        # fill the bounded online-write batch and displace the one hard reject
        # that actually changed now.
        status_changed = (
            str(row.get("status_changed_this_run") or "").strip().lower() == "true"
            and str(row.get("last_status_changed_at") or "") == str(run_now or "")
        )
        if is_new or status_changed:
            selected.append(row)
    return selected


